package onnxrt

import (
	"math"
	"os"
	"path/filepath"
	"sort"
	"testing"
)

// fuzzTol controls the differential comparison against onnxruntime for the
// randomized cases under testdata/fuzz (generated by cmd/genfuzz, goldens by
// testdata/run_golden.py). An element passes when its absolute error is
// under absTol or its relative error under relTol; NaN matches NaN and
// infinities must agree in sign.
const (
	fuzzAbsTol = 1e-4
	fuzzRelTol = 1e-3
)

// compareFuzzTensor compares got against the golden want, tolerating NaN and
// reporting the worst element. It fails the test on shape/dtype mismatch and
// on any element beyond tolerance.
func compareFuzzTensor(t *testing.T, name string, got, want *Tensor) {
	t.Helper()
	if !shapeEqual(got.Shape, want.Shape) {
		t.Errorf("%s: shape %v != golden %v", name, got.Shape, want.Shape)
		return
	}
	if got.DType != want.DType {
		t.Errorf("%s: dtype %v != golden %v", name, got.DType, want.DType)
		return
	}
	if got.DType == DInt64 {
		for i := range got.I64 {
			if got.I64[i] != want.I64[i] {
				t.Errorf("%s: int64 mismatch at flat index %d: %d != %d", name, i, got.I64[i], want.I64[i])
				return
			}
		}
		return
	}
	worst, worstGot, worstWant := 0.0, float32(0), float32(0)
	worstIdx := -1
	bad := 0
	for i := range got.F32 {
		g, w := got.F32[i], want.F32[i]
		if math.IsNaN(float64(g)) || math.IsNaN(float64(w)) {
			if math.IsNaN(float64(g)) && math.IsNaN(float64(w)) {
				continue
			}
			t.Errorf("%s: NaN mismatch at flat index %d: got %v want %v", name, i, g, w)
			bad++
			if bad >= 5 {
				return
			}
			continue
		}
		if math.IsInf(float64(g), 0) || math.IsInf(float64(w), 0) {
			if g == w {
				continue
			}
			t.Errorf("%s: Inf mismatch at flat index %d: got %v want %v", name, i, g, w)
			bad++
			if bad >= 5 {
				return
			}
			continue
		}
		d := math.Abs(float64(g) - float64(w))
		if d > worst {
			worst, worstGot, worstWant, worstIdx = d, g, w, i
		}
		if d > fuzzAbsTol && d > fuzzRelTol*math.Abs(float64(w)) {
			t.Errorf("%s: element %d: got %v want %v (abs diff %g)", name, i, g, w, d)
			bad++
			if bad >= 5 {
				return
			}
		}
	}
	if worstIdx >= 0 {
		t.Logf("%s: max abs diff %g at %d (got %v want %v)", name, worst, worstIdx, worstGot, worstWant)
	}
}

// TestFuzzGolden runs every randomized case under testdata/fuzz that has an
// onnxruntime outputs.json and compares this runtime against the golden.
// Cases are produced by cmd/genfuzz (seeded) and testdata/run_golden.py.
func TestFuzzGolden(t *testing.T) {
	// ONNXRT_FUZZ_DIR overrides the case directory, e.g. to sweep extra
	// generator seeds without replacing the committed cases.
	root := os.Getenv("ONNXRT_FUZZ_DIR")
	if root == "" {
		root = filepath.Join("testdata", "fuzz")
	}
	entries, err := os.ReadDir(root)
	if err != nil {
		t.Skip("no fuzz testdata; run cmd/genfuzz and testdata/run_golden.py first")
	}
	ran := 0
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		dir := filepath.Join(root, e.Name())
		if _, err := os.Stat(filepath.Join(dir, "outputs.json")); err != nil {
			continue // golden not generated (e.g. no onnxruntime on this host)
		}
		ran++
		t.Run(e.Name(), func(t *testing.T) {
			in := readGolden[goldenInputs](t, filepath.Join(dir, "inputs.json"))
			want := readGolden[goldenOutputs](t, filepath.Join(dir, "outputs.json"))
			g, err := LoadGraph(filepath.Join(dir, "model.onnx"))
			if err != nil {
				t.Fatal(err)
			}
			inputs := map[string]*Tensor{}
			for name, gt := range in.Inputs {
				inputs[name] = gt.tensor(t)
			}
			outs, err := g.Run(inputs)
			if err != nil {
				t.Fatal(err)
			}
			names := make([]string, 0, len(want.Outputs))
			for name := range want.Outputs {
				names = append(names, name)
			}
			sort.Strings(names)
			for _, name := range names {
				got, ok := outs[name]
				if !ok {
					t.Errorf("output %q missing", name)
					continue
				}
				compareFuzzTensor(t, name, got, want.Outputs[name].tensor(t))
			}
		})
	}
	if ran == 0 {
		t.Skip("no fuzz golden outputs; run testdata/run_golden.py first")
	}
}
